export interface Employee {
  id: string;
  fullName: string;
  annualSalaryCents: number;
  payFrequency: "weekly" | "biweekly" | "semimonthly" | "monthly";
  department: string;
  startDate: string;
}

export interface EmployeeV1 {
  id: string;
  name: string;
  salary: number;
  payFrequency: "biweekly" | "monthly";
  department: string;
  startDate: string;
}

export interface EmployeeV2 {
  id: string;
  fullName: string;
  compensation: { annualSalaryCents: number; currency: "USD"; payFrequency: Employee["payFrequency"] };
  department: string;
  startDate: string;
}

export function fromV1Create(body: any): Omit<Employee, "id"> {
  if (typeof body.salary !== "number" || body.salary <= 0) {
    throw new RangeError("salary must be a positive number of dollars");
  }
  return {
    fullName: String(body.name),
    annualSalaryCents: Math.round(body.salary * 100),
    payFrequency: body.payFrequency === "monthly" ? "monthly" : "biweekly",
    department: String(body.department),
    startDate: String(body.startDate),
  };
}

export function fromV2Create(body: any): Omit<Employee, "id"> {
  const c = body.compensation ?? {};
  if (!Number.isInteger(c.annualSalaryCents) || c.annualSalaryCents <= 0) {
    throw new RangeError("compensation.annualSalaryCents must be a positive integer");
  }
  return {
    fullName: String(body.fullName),
    annualSalaryCents: c.annualSalaryCents,
    payFrequency: c.payFrequency,
    department: String(body.department),
    startDate: String(body.startDate),
  };
}

export function toV1(e: Employee): EmployeeV1 {
  return {
    id: e.id,
    name: e.fullName,
    salary: e.annualSalaryCents,
    payFrequency: e.payFrequency === "monthly" || e.payFrequency === "semimonthly" ? "monthly" : "biweekly",
    department: e.department,
    startDate: e.startDate,
  };
}

export function toV2(e: Employee): EmployeeV2 {
  return {
    id: e.id,
    fullName: e.fullName,
    compensation: { annualSalaryCents: e.annualSalaryCents, currency: "USD", payFrequency: e.payFrequency },
    department: e.department,
    startDate: e.startDate,
  };
}

import express, { Router } from "express";
import { fromV1Create, fromV2Create, toV1, toV2, Employee } from "./employeeAdapters";
import { EmployeeStore } from "./employeeStore";

interface VersionAdapter {
  parseCreate(body: unknown): Omit<Employee, "id">;
  render(e: Employee): unknown;
}

const adapters: Record<"v1" | "v2", VersionAdapter> = {
  v1: { parseCreate: fromV1Create, render: toV1 },
  v2: { parseCreate: fromV2Create, render: toV2 },
};

function employeeRoutes(store: EmployeeStore, adapter: VersionAdapter, deprecated: boolean): Router {
  const r = express.Router();

  r.use((_req, res, next) => {
    if (deprecated) {
      res.setHeader("Deprecation", "true");
      res.setHeader("Link", '</v2/employees>; rel="successor-version"');
    }
    next();
  });

  r.post("/employees", async (req, res, next) => {
    try {
      const input = adapter.parseCreate(req.body);
      const created = await store.create(input);
      res.status(201).json(adapter.render(created));
    } catch (err) {
      if (err instanceof RangeError) return res.status(422).json({ error: err.message });
      next(err);
    }
  });

  r.get("/employees/:id", async (req, res, next) => {
    try {
      const e = await store.get(req.params.id);
      if (!e) return res.status(404).json({ error: "employee_not_found" });
      res.json(adapter.render(e));
    } catch (err) {
      next(err);
    }
  });

  return r;
}

export function mountPayrollApi(app: express.Express, store: EmployeeStore) {
  app.use("/v1", employeeRoutes(store, adapters.v1, true));
  app.use("/v2", employeeRoutes(store, adapters.v2, false));
}
